    serviceInstances,
    instanceSecrets,
    autoSwitchNetwork,
    treatVpnAsHome,
    homeNetworks,
    servicesOrder,
    dashboards,
    activeDashboardId,
    wolDevices,
    shortcuts,
    hapticsEnabled,
    globalCustomHeaders,
    uiScale,
    appTheme,
    weekStart,
    notificationSettings: notifSettings,
  } = useConfigStore.getState();
  const { url, sharedSecret, deviceId, ignoreCertErrors } = useBackendStore.getState();

  return {
    version: CURRENT_CONFIG_VERSION,
    exportedAt: new Date().toISOString(),
    services: serviceInstances,
    secrets: instanceSecrets,
    // v22: activeInstance is now per-dashboard, serialized inside the
    // `dashboards` array — no top-level field.
    autoSwitchNetwork,
    treatVpnAsHome,
    homeNetworks,
    servicesOrder,
    dashboards,
    activeDashboardId,
    backend: { url, sharedSecret, deviceId, ignoreCertErrors },
    notificationSettings: notifSettings,
    wolDevices,
    shortcuts,
    hapticsEnabled,
    globalCustomHeaders,
    uiScale,
    appTheme,
    weekStart,
  };
}

