  if (raw.servicesOrder !== undefined && raw.servicesOrder !== null) {
    if (!Array.isArray(raw.servicesOrder)) throw new Error("Config servicesOrder is invalid");
    if (raw.servicesOrder.length > SERVICE_IDS.length) {
