import {
  DEFAULT_DASHBOARD_NAME,
  DEFAULT_DASHBOARD_WIDGETS,
  DEFAULT_UI_SCALE,
  SERVICE_DEFAULTS,
  SERVICE_IDS,
} from "@/lib/constants";
import type { ServiceId } from "@/lib/constants";
import { DEFAULT_APP_THEME } from "@/lib/app-themes";
import { DEFAULT_DASHBOARD_COLOR } from "@/lib/dashboard-colors";
import { DEFAULT_DASHBOARD_ICON } from "@/lib/dashboard-defaults";
import { generateInstanceId } from "@/lib/instance-id";
import { CURRENT_CONFIG_VERSION } from "@/store/config-migrations";
import type {
  Dashboard,
  ExportPayload,
  NotificationSettings,
  ServiceConfig,
  ServiceInstance,
} from "@/lib/config-types";

/**
 * Fresh-install defaults, shared by the app store and the backend's web editor
 * ("New configuration"). Pure: no React Native or Expo imports.
 */

export const DEFAULT_NOTIFICATION_SETTINGS: NotificationSettings = {
  enabled: true,
  torrentCompleted: true,
  sabnzbdCompleted: true,
  nzbgetCompleted: true,
  radarrDownloaded: true,
  sonarrDownloaded: true,
  // Opt-in (#464), and must match the backend's schema default so the
  // per-instance "Use default" label is truthful there too.
  radarrGrabbed: false,
  sonarrGrabbed: false,
  serviceOffline: true,
  overseerrNewRequest: true,
  // Tracearr defaults mirror Tracearr's own webhook-channel routing: alerts and
  // server status on, trust-score and stream chatter off (opt-in per instance).
  tracearrViolation: true,
  tracearrNewDevice: true,
  tracearrTrustScore: false,
  tracearrServerDown: true,
  tracearrServerUp: true,
  tracearrStreamStarted: false,
  tracearrStreamStopped: false,
  // Cleanuparr (#486): removals on, routine seeding cleanups opt-in. Must match
  // the backend's schema defaults, which is what "Use default" reports.
  cleanuparrRemoved: true,
  cleanuparrCleaned: false,
};

export function defaultServiceConfig(id: ServiceId): ServiceConfig {
  const defaults = SERVICE_DEFAULTS[id];
  return {
    enabled: false,
    name: defaults.name,
    localUrl: "",
    remoteUrl: "",
    useRemote: false,
    ignoreCertErrors: false,
  };
}

// Build a single ServiceInstance with a freshly-generated UUID and the given
// (optional) overrides on top of the kind defaults.
export function makeInstance(
  id: ServiceId,
  init?: Partial<Omit<ServiceInstance, "id">>,
): ServiceInstance {
  return { id: generateInstanceId(), ...defaultServiceConfig(id), ...(init ?? {}) };
}

// Default state for a fresh install: each kind starts with one disabled
// instance carrying default URLs/credentials, mirroring the v12 UX where every
// service had a slot ready in settings.
export function defaultInstances(): Record<ServiceId, ServiceInstance[]> {
  const out = {} as Record<ServiceId, ServiceInstance[]>;
  for (const id of SERVICE_IDS) {
    out[id] = [makeInstance(id)];
  }
  return out;
}

// Build the auto-created Default dashboard for a fresh install. Each entry in
// DEFAULT_DASHBOARD_WIDGETS becomes a slot with a generated UUID and no
// per-slot settings (widgets fall back to their registry-declared defaults).
// v20: `attachedInstances` stays undefined so the auto-attach semantic
// (every current and future instance is included) covers fresh installs
// without requiring the user to revisit the picker every time they add a
// new instance. Once they open the editor and save, the dashboard
// transitions to an explicit list — i.e. they're in curated mode.
export function defaultDashboards(): Dashboard[] {
  return [
    {
      id: generateInstanceId(),
      name: DEFAULT_DASHBOARD_NAME,
      widgets: DEFAULT_DASHBOARD_WIDGETS.map((widgetId) => ({
        id: generateInstanceId(),
        widgetId,
      })),
      icon: DEFAULT_DASHBOARD_ICON,
      color: DEFAULT_DASHBOARD_COLOR,
      pinnedTabs: ["downloads", "calendar", "services"],
    },
  ];
}

/**
 * A complete, valid configuration for a brand-new install, at the current
 * schema version. What the web editor's "New configuration" starts from; it
 * validates unchanged through `validateExportPayload` and restores through the
 * app's normal import path. No `backend` block (a restoring phone keeps its
 * own pairing) and no `weekStart` (the phone resolves "auto" from the device).
 */
export function blankExportPayload(): ExportPayload {
  const dashboards = defaultDashboards();
  return {
    version: CURRENT_CONFIG_VERSION,
    exportedAt: new Date().toISOString(),
    services: defaultInstances(),
    secrets: {},
    autoSwitchNetwork: false,
    treatVpnAsHome: false,
    homeNetworks: [],
    servicesOrder: [],
    dashboards,
    activeDashboardId: dashboards[0]!.id,
    notificationSettings: { ...DEFAULT_NOTIFICATION_SETTINGS },
    wolDevices: [],
    shortcuts: [],
    hapticsEnabled: true,
    globalCustomHeaders: {},
    uiScale: DEFAULT_UI_SCALE,
    appTheme: DEFAULT_APP_THEME,
  };
}
=====TYPES
import type { ServiceId, WidgetId, UiScale } from "@/lib/constants";
import type { SeerrAuthMode } from "@/lib/seerr-auth";
import type { AppThemeId } from "@/lib/app-themes";
import type { WeekStart } from "@/lib/week-start-values";

/**
 * The configuration payload types: what the store holds, what the export file
 * carries, and what the backend backup slots contain. Pure on purpose — this
 * module is bundled into the backend's web editor alongside store/config-schema
 * and store/config-migrations, so it must never import React Native, Expo or
 * the store itself. store/config-store.ts re-exports everything here.
 */

export interface WakeOnLanDevice {
  id: string;
  name: string;
  mac: string;
  broadcastAddress?: string;
  port?: number;
}

// A user-defined web shortcut shown on the Shortcuts dashboard widget (#344).
// `icon` is a lucide name from lib/dashboard-icons.ts and `color` a hex from
// lib/dashboard-colors.ts; both are optional and fall back at render time.
export interface WebShortcut {
  id: string;
  name: string;
  url: string;
  icon?: string;
  color?: string;
}

export interface HomeNetwork {
  id: string;
  ssid: string;
  // Optional AP MAC pin. Empty string means SSID-only match for this entry —
  // the rogue-AP guard from v6 lives per-entry now so each AP in a mesh can
  // carry its own pin.
  bssid: string;
}

// Per-service connection config (URLs, enabled flag, display name). One
// ServiceInstance row exists per configured server — users can have multiple
// rows of the same kind (e.g. two qBittorrents).
export interface ServiceConfig {
  enabled: boolean;
  name: string;
  localUrl: string;
  remoteUrl: string;
  useRemote: boolean;
  // v23: opt this server out of TLS certificate validation (accept self-signed
  // / otherwise-invalid certs). Per-instance and off by default. The hostnames
  // of instances with this on are pushed to the native layer (see
  // lib/insecure-tls.ts), which bypasses trust evaluation for exactly those
  // hosts. Absent/undefined behaves like false.
  ignoreCertErrors?: boolean;
  // v60 (#394): the Remote URL is a VPN-side address (Tailscale, WireGuard,
  // ...). While no VPN is connected the app skips that slot instead of probing
  // it: the health poll reports "Waiting for VPN" rather than offline, and
  // requests fail fast rather than paying the connect timeout. Scoped to the
  // Remote URL slot on purpose: with auto-switch the Local URL is only ever
  // used on a confirmed home network, where the LAN needs no tunnel; a server
  // with no LAN address pairs this with `useRemote`. Absent/undefined behaves
  // like false, which is the pre-v60 behavior.
  remoteRequiresVpn?: boolean;
  // v36 (#287): per-instance defaults preselected in the arr add flows
  // (components/common/add-media-sheet.tsx). Absent/undefined keeps the
  // previous "first in the server's list" behavior; a stale value (profile or
  // folder deleted upstream) also falls back to first-in-list at add time.
  // defaultMetadataProfileId is Lidarr-only.
  defaultQualityProfileId?: number;
  defaultRootFolderPath?: string;
  defaultMetadataProfileId?: number;
  // v41 (#289): qBittorrent-only — tag torrents added manually from the app
  // with "Dashboarr" so server-side scripts/filters can identify their origin.
  // Off by default (absent/undefined behaves like false) because enabling it
  // writes a tag into the user's qBittorrent config on first use.
  tagAddedTorrents?: boolean;
  // v52 (#332): Seerr-only — file every request from this instance on behalf of
  // another Seerr account, so a household sharing one admin API key can still
  // see who asked for what. Absent/undefined keeps the previous behavior: the
  // request is attributed to the API key's own identity (the admin). A stale id
  // (user deleted upstream) makes Seerr reject the request rather than silently
  // fall back, so the settings card re-resolves the id against the live user
  // list and shows it as unknown when it no longer matches.
  requestAsUserId?: number;
  // v57 (#386): unRAID-only — the id of the Glances instance that supplies
  // per-disk read/write rates for this server's drives. unRAID's own API
  // hardcodes numReads/numWrites to 0 and has no throughput field, so the only
  // source is a Glances running on the same machine. Deliberately an explicit
  // pairing rather than a guess: matching the two by URL hostname looks right
  // but isn't (one public hostname can port-forward to different machines), and
  // a wrong match paints another server's disk activity onto these drives.
  // Absent/undefined means no I/O is shown and no Glances query is made. A
  // stale id (instance deleted) reads as absent.
  diskIoInstanceId?: string;
  // v61: Bazarr-only — which Radarr / Sonarr instance this Bazarr manages
  // subtitles for, so the movie and series pages know which Bazarr to ask.
  //   absent/undefined → automatic: the app reads Bazarr's own Radarr/Sonarr
  //                      settings and links the instance whose API key matches
  //                      (an API key identifies one server, unlike a hostname)
  //   an instance id   → set by the user, wins over detection
  //   ARR_LINK_OFF     → explicitly not linked; nothing is detected
  // A stale id (instance deleted) reads as unlinked until changed.
  linkedRadarrInstanceId?: string;
  linkedSonarrInstanceId?: string;
  // v53 (#332): Seerr-only sign-in mode. Absent/undefined means the admin
  // API key (the pre-v53 behavior). The three session values ride Seerr's
  // login cookie instead; see lib/seerr-auth.ts for what each one posts and
  // which secret slot it reads. Only the editor writes this, and it writes
  // `undefined` rather than "apiKey" so exports keep the absent shape.
  authMode?: SeerrAuthMode;
}

// Stored in linkedRadarrInstanceId / linkedSonarrInstanceId to switch the
// automatic Bazarr → Radarr/Sonarr link off. Instance ids are UUIDs, so this
// never collides with a real one.
export const ARR_LINK_OFF = "none";

// A configured service instance: a ServiceConfig plus a stable UUID `id` that
// keys per-instance secrets, query cache, and per-instance widget bindings.
// The UUID is generated on instance creation and is preserved across renames,
// reorders, and exports/imports.
export interface ServiceInstance extends ServiceConfig {
  id: string;
}

export interface ServiceSecrets {
  apiKey?: string;
  username?: string;
  password?: string;
  // Per-service custom HTTP headers (e.g. CF-Access-Client-Id for reverse-proxy
  // auth). Stored alongside other secrets in SecureStore because values often
  // contain bearer tokens.
  customHeaders?: Record<string, string>;
}

// Per-slot settings live as an opaque record on the slot itself. The widget
// registry owns the shape (via defaultSettings) — the store just persists what
// each widget hands back. Values must be plain JSON-serializable objects.

