import { getBoolean, setBoolean } from "@/store/storage";

// The "Add list exclusion" box on the *arr delete confirms (#472) starts
// unchecked and then remembers the last choice, the way Radarr's and Sonarr's
// own web UIs persist `deleteOptions` (their default is false). It is written
// on toggle, like upstream, so ticking it and then cancelling still sticks.
// Delete Files is not remembered: it is picked in the action sheet that opens
// the confirm.
//
// Kept per service kind, not per instance, matching upstream (one web UI, one
// remembered choice), and kept out of the exported config like the other
// `ui.*` keys: a local convenience, not a setting worth backing up. Plain
// functions over the sync storage cache, so there is nothing to hydrate.

export type DeleteExclusionKind = "radarr" | "sonarr" | "lidarr";

export function deleteExclusionKey(kind: DeleteExclusionKind): string {
  return `ui.deleteExclusion.${kind}`;
}

export function getDeleteExclusionPref(kind: DeleteExclusionKind): boolean {
  return getBoolean(deleteExclusionKey(kind));
}

export function setDeleteExclusionPref(
  kind: DeleteExclusionKind,
  value: boolean,
): void {
  setBoolean(deleteExclusionKey(kind), value);
}
=====use-instance-target
import { useConfigStore } from "@/store/config-store";
import { useShallow } from "zustand/react/shallow";
import type { ServiceId } from "@/lib/constants";
import type { ServiceInstance } from "@/store/config-store";

/**
 * The ordered list of enabled instances for a kind. Used by aggregated
 * dashboard cards to fan a query out across every configured instance via
 * TanStack Query's `useQueries`.
 *
 * `useShallow` is load-bearing here: `.filter()` always returns a new array,
 * so without shallow equality every store change would re-trigger the parent's
 * `useQueries`, which rebuilds its query list and re-renders, in an infinite
 * loop. With shallow equality the selector only signals a change when the
 * filtered ids/names/etc. actually differ.
 */
export function useEnabledInstances(serviceId: ServiceId): ServiceInstance[] {
  return useConfigStore(
    useShallow((s) =>
      (s.serviceInstances[serviceId] ?? []).filter((i) => i.enabled),
    ),
  );
}

/**
 * Resolve which instance a per-service hook should query and whether it's
 * enabled. Pass `instanceId` to target a specific instance (used by aggregated
 * dashboard cards that render one slot per instance); omit it to follow the
 * user's currently-selected instance for that kind (used by per-service tabs).
 *
 * The returned `instanceId` is also what callers should fold into TanStack
 * Query keys so two configured instances never collide in the query cache.
 */
export function useInstanceTarget(
  serviceId: ServiceId,
  instanceId?: string,
): { instanceId: string | null; enabled: boolean } {
  // Only the workspace-resolved active instance (attachment + enabled aware).
  // No raw serviceInstances[serviceId][0] tail: when nothing is enabled+attached
  // in the active workspace this is null, which gates dependent queries off via
  // `enabled` below — instead of silently following another workspace's
  // instance and rendering its data (#3).
  const activeId = useConfigStore((s) => s.activeInstance[serviceId] ?? null);
  const targetId = instanceId ?? activeId;
  const enabled = useConfigStore((s) => {
    if (!targetId) return false;
    const list = s.serviceInstances[serviceId] ?? [];
    return list.find((i) => i.id === targetId)?.enabled ?? false;
  });
  return { instanceId: targetId, enabled };
}

/**
 * The full ServiceInstance a sheet or settings card is targeting: the explicit
 * `instanceId` when given, otherwise the workspace-resolved active instance for
 * the kind. Used to read per-instance preferences (e.g. the arr add-flow
 * defaults) alongside the instance-scoped profile/folder hooks.
 *
 * Returns a stable array-element reference from the store, so no `useShallow`
 * is needed — the selector only signals a change when the resolved instance
 * object itself changes.
 */
export function useTargetInstance(
  serviceId: ServiceId,
  instanceId?: string,
): ServiceInstance | undefined {
  return useConfigStore((s) => {
    const targetId = instanceId ?? s.activeInstance[serviceId] ?? null;
    if (!targetId) return undefined;
    return (s.serviceInstances[serviceId] ?? []).find((i) => i.id === targetId);
  });
}
=====use-active-instance
import { useMemo } from "react";
import { useConfigStore } from "@/store/config-store";
import { useShallow } from "zustand/react/shallow";
import { useAttachedInstances } from "@/hooks/use-active-dashboard";
import type { ServiceId } from "@/lib/constants";
import type { ServiceInstance } from "@/store/config-store";

/**
 * Read + set the currently-selected instance for a service kind. Used by the
 * per-service tab chip switcher: when the user taps a chip, the setter writes
 * the new UUID to `activeInstance[serviceId]`, which auto-cascades through
 * every per-service hook (their `useInstanceTarget` selector flips), the
 * legacy `state.services[id]` derived view, and the persisted store.
 *
 * `instances` is the ordered list filtered to enabled AND attached to the
 * active workspace. Without the attachment filter, the picker would offer
 * instances the workspace doesn't include — taps on those would write a pin
 * that `deriveActiveInstance` then rejects, snapping the selection back to
 * the first attached instance with no feedback.
 *
 * `activeId` falls back to the first enabled+attached instance when the
 * workspace has no explicit pin, matching `deriveActiveInstance`'s behavior.
 */
export function useActiveInstance(serviceId: ServiceId): {
  instances: ServiceInstance[];
  activeId: string | null;
  setActiveId: (id: string) => void;
} {
  const attached = useAttachedInstances();
  // useShallow stops the new-array-every-render reference instability that
  // would otherwise re-render the parent on every unrelated store update.
  const rawInstances = useConfigStore(
    useShallow((s) => s.serviceInstances[serviceId] ?? []),
  );
  const instances = useMemo(
    () => rawInstances.filter((i) => i.enabled && attached.has(i.id)),
    [rawInstances, attached],
  );
  const activeId = useConfigStore((s) => s.activeInstance[serviceId]) ??
    instances[0]?.id ??
    null;
  const setActiveInstance = useConfigStore((s) => s.setActiveInstance);
  return {
    instances,
    activeId,
    setActiveId: (id: string) => setActiveInstance(serviceId, id),
  };
}
=====use-torrent-targets
import { useConfigStore } from "@/store/config-store";
import { useAttachedKinds } from "@/hooks/use-active-dashboard";
import { useActiveInstance } from "@/hooks/use-active-instance";
import type { ServiceInstance } from "@/store/config-store";

export type TorrentClientId =
  | "qbittorrent"
  | "rtorrent"
  | "transmission"
  | "deluge";

// One candidate destination for a magnet/torrent link: a torrent client kind +
// a specific configured instance of it.
export interface TorrentTarget {
  client: TorrentClientId;
  instanceId: string;
  label: string;
}

export const TORRENT_CLIENT_LABELS: Record<TorrentClientId, string> = {
  qbittorrent: "qBittorrent",
  rtorrent: "rTorrent",
  transmission: "Transmission",
  deluge: "Deluge",
};

/**
 * Every place a magnet/torrent link can be sent: each enabled + workspace-
 * attached instance of each enabled torrent client. Single source of truth for
 * the Downloads tab's incoming-magnet picker and the Jackett grab flow, so
 * "which clients can receive a link" can't drift between the two.
 */
export function useTorrentTargets(): TorrentTarget[] {
  const qbEnabled = useConfigStore((s) => s.services.qbittorrent.enabled);
  const rtEnabled = useConfigStore((s) => s.services.rtorrent?.enabled ?? false);
  const trEnabled = useConfigStore((s) => s.services.transmission?.enabled ?? false);
  const dgEnabled = useConfigStore((s) => s.services.deluge?.enabled ?? false);
  const attachedKinds = useAttachedKinds();
  const qbInstances = useActiveInstance("qbittorrent").instances;
  const rtInstances = useActiveInstance("rtorrent").instances;
  const trInstances = useActiveInstance("transmission").instances;
  const dgInstances = useActiveInstance("deluge").instances;

  const kinds: [TorrentClientId, boolean, ServiceInstance[]][] = [
    ["qbittorrent", qbEnabled, qbInstances],
    ["rtorrent", rtEnabled, rtInstances],
    ["transmission", trEnabled, trInstances],
    ["deluge", dgEnabled, dgInstances],
  ];

  return kinds.flatMap(([kind, enabled, instances]) =>
    enabled && attachedKinds.has(kind)
      ? instances.map((i) => ({
          client: kind,
          instanceId: i.id,
          // Only disambiguate with the instance name when the kind has several
          // instances — "qBittorrent · Seedbox" vs just "qBittorrent".
          label:
            instances.length > 1
              ? `${TORRENT_CLIENT_LABELS[kind]} · ${i.name || i.id}`
              : TORRENT_CLIENT_LABELS[kind],
        }))
      : [],
  );
}

