 * the neutral one the parser would have produced for a first release.
 */
export function qualityFromDefinition(quality: {
  id: number;
  name: string;
  source?: string;
  resolution?: number;
}): ArrQualityModel {
  return { quality, revision: { version: 1, real: 0, isRepack: false } };
}

