import { randomBytes } from "node:crypto";
import { getDb } from "../client.js";

const TOKEN_TTL_MS = 10 * 60 * 1000; // 10 minutes

interface PairingRow {
  token: string;
  expires_at: number;
  claimed_at: number | null;
}

export function createPairingToken(): { token: string; expiresAt: number } {
  const token = randomBytes(16).toString("hex");
  const expiresAt = Date.now() + TOKEN_TTL_MS;
  getDb()
    .prepare("INSERT INTO pairing_tokens (token, expires_at, claimed_at) VALUES (?, ?, NULL)")
    .run(token, expiresAt);
  return { token, expiresAt };
}

/**
 * Attempt to claim a pairing token. Returns true on success (atomic CAS).
 * A claimed token cannot be reused.
 */
export function claimPairingToken(token: string): boolean {
  const now = Date.now();
  const result = getDb()
    .prepare(
      `UPDATE pairing_tokens
       SET claimed_at = ?
       WHERE token = ? AND claimed_at IS NULL AND expires_at > ?`,
    )
    .run(now, token, now);
  return result.changes === 1;
}

export function getPairingToken(token: string): PairingRow | null {
  const row = getDb()
    .prepare<[string], PairingRow>("SELECT * FROM pairing_tokens WHERE token = ?")
    .get(token);
  return row ?? null;
}

/**
 * Current unexpired + unclaimed token, if any. `ensureActiveToken` reuses it so
 * a restart inside the 10-minute TTL reprints the same QR instead of
 * invalidating the one the user is currently looking at. (Originally written for
 * a /pair HTML page that no longer exists — token minting is startup-log-only
 * now, see routes/pair.ts.)
 */
export function getActiveToken(): string | null {
  const row = getDb()
    .prepare<[number], PairingRow>(
      `SELECT * FROM pairing_tokens
       WHERE claimed_at IS NULL AND expires_at > ?
       ORDER BY expires_at DESC
       LIMIT 1`,
    )
    .get(Date.now());
  return row ? row.token : null;
}

export function ensureActiveToken(): { token: string; expiresAt: number } {
  const existing = getActiveToken();
  if (existing) {
    const row = getPairingToken(existing);
    if (row) return { token: existing, expiresAt: row.expires_at };
  }
  return createPairingToken();
}

export function purgeExpiredTokens(): void {
  getDb()
    .prepare("DELETE FROM pairing_tokens WHERE expires_at < ? OR claimed_at IS NOT NULL")
    .run(Date.now() - 24 * 60 * 60 * 1000);
}
=====web-slot-watch
import { STORAGE_KEYS } from "@/lib/constants";
import { listConfigBackups, WEB_SLOT_ID } from "@/services/backend-api";
import type { BackupMeta } from "@/services/backend-api";
import { useBackendStore } from "@/store/backend-store";
import { uploadConfigBackup } from "@/services/backend-backup";
import { deleteKey, getString, setString } from "@/store/storage";

/**
 * Keeps the backend store's view of the "web" slot current (Refs #385).
 *
 * Rules, in order of trust:
 * - A successful list is authoritative: the web slot's revision, or null when
 *   there is none.
 * - A backend that answers 404 or 400 does not have the feature; treat as none.
 * - A network error preserves the last known value.
 * - The applied revision comes from the envelope the phone actually restored
 *   (never from a list or the phone clock) and is cleared on unpair.
 */

const THROTTLE_MS = 5 * 60 * 1000;
let lastCheckedAt = 0;
let inflight: Promise<void> | null = null;

export function noteBackupList(backups: BackupMeta[]): void {
  const state = useBackendStore.getState();
  const web = backups.find((b) => b.deviceId === WEB_SLOT_ID);
  state.setWebSlot({ webSlotRevision: web ? web.revision : null });
  // Authoritative list with no slot of our own while backup is on: the slot
  // was deleted or the backend reset. The unchanged-hash skip would otherwise
  // keep us unbacked forever, so force one upload.
  if (state.backupEnabled && !backups.some((b) => b.mine)) {
    deleteKey(STORAGE_KEYS.backendBackupLastHash);
    void uploadConfigBackup({ force: true }).catch((err) => {
      console.warn("[backend-backup] re-upload after missing slot failed", err);
    });
  }
}

function isUnsupported(err: unknown): boolean {
  const status = (err as { status?: number } | null)?.status;
  return status === 404 || status === 400;
}

export function checkWebSlot(opts: { force?: boolean } = {}): Promise<void> {
  const state = useBackendStore.getState();
  if (!state.hydrated || !state.url || !state.sharedSecret) return Promise.resolve();
  const now = Date.now();
  if (!opts.force && now - lastCheckedAt < THROTTLE_MS) return Promise.resolve();
  if (inflight) return inflight;
  lastCheckedAt = now;
  inflight = listConfigBackups()
    .then(({ backups }) => noteBackupList(backups))
    .catch((err: unknown) => {
      if (isUnsupported(err)) useBackendStore.getState().setWebSlot({ webSlotRevision: null });
      // Anything else (offline, timeout): keep what we knew.
    })
    .finally(() => {
      inflight = null;
    });
  return inflight;
}

/** For tests and unpair: forget the throttle window. */
export function resetWebSlotWatch(): void {
  lastCheckedAt = 0;
}

export function markWebSlotApplied(revision: number): void {
  setString(STORAGE_KEYS.backendWebSlotAppliedRevision, String(revision));
  useBackendStore.getState().setWebSlot({ webSlotAppliedRevision: revision });
}

export function clearWebSlotApplied(): void {
  deleteKey(STORAGE_KEYS.backendWebSlotAppliedRevision);
  useBackendStore.getState().setWebSlot({ webSlotAppliedRevision: null });
}

/** Restore the persisted applied revision after both stores hydrated. */
export function loadWebSlotStatus(): void {
  const raw = getString(STORAGE_KEYS.backendWebSlotAppliedRevision);
  const n = raw ? Number(raw) : NaN;
  useBackendStore.getState().setWebSlot({ webSlotAppliedRevision: Number.isFinite(n) ? n : null });
}

