import { useBackendStore } from "@/store/backend-store";
import { useConfigStore } from "@/store/config-store";
import { SERVICE_IDS } from "@/lib/constants";
import { seerrAuthMode, seerrUsesSession } from "@/lib/seerr-auth";
import { isPrivateHost } from "@/lib/url-validation";
import { describeBackendTransportError } from "@/lib/backend-error";
import {
  LEGACY_BACKEND_NOTIF_CATEGORIES,
  restrictPerInstanceCategories,
} from "@/lib/notification-categories";
import type { EncryptedEnvelope } from "@/lib/config-crypto";
import type { NotificationSettings } from "@/lib/config-types";

const DEFAULT_TIMEOUT = 10000;

interface RequestOptions extends Omit<RequestInit, "signal"> {
  timeout?: number;
  baseUrl?: string;
  sharedSecret?: string | null;
}

async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
  const state = useBackendStore.getState();
  const baseUrl = options.baseUrl ?? state.url;
  const sharedSecret = options.sharedSecret !== undefined ? options.sharedSecret : state.sharedSecret;

  if (!baseUrl) throw new Error("Backend not paired");

  const headers = new Headers(options.headers);
  if (sharedSecret) headers.set("Authorization", `Bearer ${sharedSecret}`);
  if (options.body && !headers.has("Content-Type")) {
    headers.set("Content-Type", "application/json");
  }

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), options.timeout ?? DEFAULT_TIMEOUT);

  const url = `${baseUrl.replace(/\/$/, "")}${path}`;

  try {
    let res: Response;
    try {
      res = await fetch(url, {
        ...options,
        headers,
        signal: controller.signal,
      });
    } catch (err) {
      // Connection-level failure (TLS / DNS / refused / timeout) — no HTTP
      // response exists. Translate it into something actionable; anything
      // carrying a `.status` is passed straight through, which is what keeps
      // `pairClaim`'s scheme fall-through correct.
      throw describeBackendTransportError(err, url);
    }
    if (!res.ok) {
      // Tag the status so callers can tell a real HTTP response (the endpoint
      // answered) apart from a connection-level failure (fetch rejects with no
      // `.status`). `pairClaim` relies on this to decide whether to retry a
      // different scheme. Existing catch sites only read `.message`, so this is
      // backwards-compatible.
      const err = new Error(`Backend ${path} HTTP ${res.status}`) as Error & {
        status?: number;
      };
      err.status = res.status;
      throw err;
    }
    const ct = res.headers.get("content-type");
    if (ct?.includes("application/json")) {
      return (await res.json()) as T;
    }
    return undefined as unknown as T;
  } finally {
    clearTimeout(timeoutId);
  }
}

/**
 * Backend `/health` has two projections (backend v1.4.0+): anonymous callers
 * get liveness only (`ok`, `name`), a valid bearer gets everything. Every field
 * beyond `ok`/`name` is therefore optional — the app always sends a bearer, so
 * it sees the full body, but typing them as required would be a lie the moment
 * anything calls this unauthenticated.
 */
export interface BackendHealth {
  ok: boolean;
  name: string;
  version?: string;
  expoAuth?: string;
  // Multi-instance backends: `id` is the per-instance UUID, `kind` is the
  // service kind, `name` is the user-facing label. Older backends omit
  // `kind`/`name` and put the kind in `id`. `useBackendHealth` only reads
  // `ok` today, but the richer fields are available for any future UI that
  // wants to surface backend-side per-instance polling status.
  pollers?: {
    id: string;
    kind?: string;
    name?: string;
    intervalMs: number;
    lastRunAt: number | null;
    lastError: string | null;
=====130-180
 * WHATWG Fetch spec; only 307/308 preserve the method), so the backend receives
 * `GET /pair/claim` and 404s (#218). 301/302 leave GET/HEAD untouched, so
 * `res.url`/`res.redirected` are unreliable for detecting this in RN — instead
 * we avoid the redirect entirely by trying https:// first for PUBLIC http hosts.
 * Private/LAN hosts (192.168.x, 10.x, *.local, localhost) legitimately run plain
 * http with no TLS, so they are never upgraded.
 */
function pairingBaseCandidates(normalizedUrl: string): string[] {
  try {
    const u = new URL(normalizedUrl);
    if (u.protocol === "http:" && !isPrivateHost(u.hostname)) {
      return [normalizedUrl.replace(/^htt<private>/\//i, "https://"), normalizedUrl];
    }
  } catch {
    // unparseable — fall through to the single-candidate path
  }
  return [normalizedUrl];
}

export async function pairClaim(
  baseUrl: string,
  token: string,
  expoPushToken: string,
  platform: "ios" | "android",
  appVersion?: string,
): Promise<PairClaimResult> {
  const candidates = pairingBaseCandidates(baseUrl.replace(/\/$/, ""));
  const body = JSON.stringify({ token, expoPushToken, platform, appVersion });
  let lastErr: unknown;
  for (const candidate of candidates) {
    try {
      const data = await request<Omit<PairClaimResult, "baseUrl">>("/pair/claim", {
        baseUrl: candidate,
        sharedSecret: null,
        method: "POST",
        body,
      });
      return { ...data, baseUrl: candidate };
    } catch (err) {
      // A numeric `.status` means the endpoint answered (e.g. 401 invalid token,
      // 400 bad payload) — a real result, not a wrong-scheme guess — so surface
      // it. Only fall through to the next candidate on a connection-level
      // failure (TLS/DNS/refused/timeout), where https simply wasn't reachable.
      if (typeof (err as { status?: number } | null)?.status === "number") throw err;
      lastErr = err;
    }
  }
  throw lastErr;
}

export function registerDevice(expoPushToken: string, platform: "ios" | "android"): Promise<void> {
=====260-396
 *
 * Sends the multi-instance shape (`instances: [{ id, kind, ... }]`). The
 * backend accepts both the new shape and the pre-multi-instance `services`
 * shape — see backend/dashboarr-backend/src/routes/config.ts — so a backend
 * that hasn't been upgraded yet won't reject this payload, it'll just
 * normalize legacy single-instance entries internally.
 *
 * Skipped in demo mode: the store then holds one fake instance per kind
 * (`http://demo.local`, no secrets), and PUT /config replaces the backend's
 * whole instance list, so a push would swap the user's real services out of
 * every poller. disableDemoMode re-hydrates the real config, and that store
 * change makes ConfigSyncBridge push it again.
 */
export async function pushConfigSnapshot(): Promise<void> {
  const configState = useConfigStore.getState();
  if (configState.demoMode) return;

  const instances = SERVICE_IDS.flatMap((kind) => {
    const list = configState.serviceInstances[kind] ?? [];
    return list.map((inst) => {
      // Pi-hole's password is not a read-only stats key: it grants
      // PUT /api/config/*, i.e. rewriting the DNS of the whole household. There
      // is no Pi-hole poller on the backend, so sending it would copy that
      // credential into a second host's SQLite for nothing. Send the instance so
      // the backend's offline poller still watches it, but never the secret.
      //
      // A Seerr signed in as a user (#332) is the same story: its secret is a
      // person's Plex token or media-server password, and the backend has no
      // session client to use it with. The backend skips its pending-request
      // poller for a Seerr instance without an API key; webhooks need none.
      //
      // Beszel is Pi-hole's case exactly: the credential is a PocketBase
      // superuser email/password, i.e. full admin over the hub, and the
      // backend has no Beszel poller at all — its only Beszel call is the
      // anonymous /api/health ping, so applyAuth deliberately sends nothing.
      const shareSecrets =
        kind !== "pihole" &&
        kind !== "beszel" &&
        !(kind === "overseerr" && seerrUsesSession(seerrAuthMode(inst)));
      const secrets = configState.instanceSecrets[inst.id] ?? {
        apiKey: "",
        username: "",
        password: "",
      };
      return {
        id: inst.id,
        kind,
        enabled: inst.enabled,
        name: inst.name,
        localUrl: inst.localUrl,
        remoteUrl: inst.remoteUrl,
        useRemote: inst.useRemote,
        apiKey: shareSecrets ? secrets.apiKey || undefined : undefined,
        username: shareSecrets ? secrets.username || undefined : undefined,
        password: shareSecrets ? secrets.password || undefined : undefined,
      };
    });
  });

  const {
    enabled,
    torrentCompleted,
    sabnzbdCompleted,
    nzbgetCompleted,
    radarrDownloaded,
    sonarrDownloaded,
    radarrGrabbed,
    sonarrGrabbed,
    serviceOffline,
    overseerrNewRequest,
    cleanuparrRemoved,
    cleanuparrCleaned,
    perInstance,
    apprise,
    qbtMutedCategories,
  } = configState.notificationSettings;

  const send = (overrides: NotificationSettings["perInstance"]) =>
    request<void>("/config", {
      method: "PUT",
      body: JSON.stringify({
        instances,
        notifications: {
          enabled,
          torrentCompleted,
          sabnzbdCompleted,
          nzbgetCompleted,
          radarrDownloaded,
          sonarrDownloaded,
          // v61 (#464). Older backends strip unknown top-level keys (zod v3).
          radarrGrabbed,
          sonarrGrabbed,
          serviceOffline,
          overseerrNewRequest,
          // v62 (#486): the defaults the per-instance Cleanuparr toggles
          // inherit. Older backends strip unknown top-level keys (zod v3).
          cleanuparrRemoved,
          cleanuparrCleaned,
          // v21: per-instance overrides. Sent as `undefined` when no overrides
          // exist so the backend treats it the same as a pre-v21 client.
          perInstance: overrides,
          // v34: Apprise sink config. Sent as `undefined` when unset so older
          // backends ignore it.
          apprise,
          // v42: per-qbt-instance muted categories (#310). Sent as `undefined`
          // when unset; older backends strip the unknown key (zod v3).
          qbtMutedCategories,
        },
      }),
    });

  // Backends up to v1.9.0 validate perInstance keys with a strict enum, so one
  // override for a category they predate (e.g. "Always notify" on Movie
  // grabbed) 400s the whole payload and the backend silently keeps its last
  // good config. Retry such a 400 once without those overrides so everything
  // else still lands; newer backends drop unknown categories themselves.
  const legacyPerInstance = restrictPerInstanceCategories(
    perInstance,
    LEGACY_BACKEND_NOTIF_CATEGORIES,
  );
  try {
    await send(perInstance);
  } catch (err) {
    const status = (err as { status?: number } | null)?.status;
    if (status !== 400 || overrideCount(legacyPerInstance) === overrideCount(perInstance)) {
      throw err;
    }
    await send(legacyPerInstance);
  }
}

function overrideCount(perInstance: NotificationSettings["perInstance"]): number {
  return Object.values(perInstance ?? {}).reduce(
    (n, overrides) => n + Object.keys(overrides ?? {}).length,
    0,
  );
}

