   * `updateBeszelToken` so a renewal that lands after the session was dropped
   * (a credential save, an instance delete) is discarded instead of
   * resurrecting the old token.
   */
  generation: number;
}

interface BeszelSessionEntry {
  token: string | null;
  authCollection: BeszelAuthCollection | null;
  obtainedAt: number | null;
  loginPromise: Promise<{ token: string; authCollection: BeszelAuthCollection }> | null;
  generation: number;
}

